func New(db *sql.DB, contractsDir, migrationFile string) (*Service, error) {
	c, e := LoadContracts(contractsDir)
	if e != nil {
		return nil, e
	}
	files, e := filepath.Glob(filepath.Join(filepath.Dir(migrationFile), "[0-9][0-9][0-9][0-9]_*.sql"))
	if e != nil {
		return nil, e
	}
	if _, e = os.Stat(migrationFile); e != nil {
		return nil, e
	}
	// Refuse future/gapped inventories before domain, additive or fence DDL.
	// The lower storage layer has already opened the file and selected WAL.
	if _, e = checkMigrationInventory(db, files); e != nil {
		return nil, e
	}
	if e = CheckMigrationSafety(db, files); e != nil {
		return nil, e
	}
	tx, e := db.Begin()
	if e != nil {
		return nil, e
	}
	defer tx.Rollback()
	for _, file := range files {
		version, err := strconv.Atoi(filepath.Base(file)[:4])
		if err != nil {
			return nil, err
		}
		if version < 2 {
			continue
		}
		var applied int
		if err := tx.QueryRow("SELECT count(*) FROM schema_migrations WHERE version=?", version).Scan(&applied); err != nil {
			return nil, err
		}
		if applied != 0 {
			continue
		}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if _, err = tx.Exec(string(b)); err != nil {
			return nil, err
		}
		if _, err = tx.Exec("INSERT OR IGNORE INTO schema_migrations(version) VALUES(?)", version); err != nil {
			return nil, err
		}
	}
	// W03's additive session schema has its own unnumbered, idempotent path.
	// The production host must install it as well as the tests and import tools.
	// Keep it in the same transaction so a missing or invalid schema cannot
	// leave the business migrations committed with the typed client unusable.
	sessionSchema, err := os.ReadFile(filepath.Join(filepath.Dir(migrationFile), "next_v24_sessions.sql"))
	if err != nil {
		return nil, err
	}
	if _, err = tx.Exec(string(sessionSchema)); err != nil {
		return nil, err
	}
	if err = installClientSessionFence(context.Background(), tx, false); err != nil {
		return nil, err
	}
	if e = tx.Commit(); e != nil {
		return nil, e
	}
	return &Service{DB: db, Contracts: c, projectBindingRoute: "THIN_CORE"}, nil
}

func CheckMigrationSafety(db *sql.DB, files []string) error {
	applied, e := checkMigrationInventory(db, files)
	if e != nil {
		return e
	}
	populated, e := migrationAuthorityPresent(db)
	if e != nil {
		return e
	}
	if !populated {
		return nil
	}
	if applied != len(files) {
		return fmt.Errorf("MIGRATION_PREBACKUP_REQUIRED: back up with matching program and verify an isolated restore before migration %d", applied+1)
	}
	raw, e := os.ReadFile(filepath.Join(filepath.Dir(files[0]), "next_v24_sessions.sql"))
	if e != nil || Digest(raw) != upgradeQueueSessionHash {
		return fmt.Errorf("MIGRATION_ADDITIVE_SOURCE")
	}
	expected, e := sql.Open("sqlite", ":memory:")
	if e != nil {
		return e
	}
	defer expected.Close()
	expected.SetMaxOpenConns(1)
	if _, e = expected.Exec(string(raw)); e != nil {
		return e
	}
	if e = installClientSessionFence(context.Background(), expected, false); e != nil {
		return e
	}
	want, e := migrationSessionSchema(expected)
	if e != nil {
		return e
	}
	got, e := migrationSessionSchema(db)
	if e != nil {
		return e
	}
	if Hash(got) != Hash(want) {
		return fmt.Errorf("MIGRATION_PREBACKUP_REQUIRED: additive session schema or fence differs")
	}
	return nil
}

func migrationAuthorityPresent(db *sql.DB) (bool, error) {
	rows, e := db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
	if e != nil {
		return false, e
	}
	names := []string{}
	for rows.Next() {
		var name string
		if e = rows.Scan(&name); e != nil {
			rows.Close()
			return false, e
		}
		names = append(names, name)
	}
	e = rows.Err()
	rows.Close()
	if e != nil {
		return false, e
	}
	for _, name := range names {
		if name == "schema_migrations" {
			continue
		}
		query := `SELECT count(*) FROM "` + strings.ReplaceAll(name, `"`, `""`) + `"`
		// Only the exact source-defined mutex seed is structural, not authority.
		if name == "resource_write_lock" {
			query += " WHERE id<>1 OR value<>0"
		}
		var n int
		if e = db.QueryRow(query).Scan(&n); e != nil {
			return false, e
		}
		if n != 0 {
			return true, nil
		}
	}
	return false, nil
}

func installClientSessionFence(ctx context.Context, ex fenceExec, restored bool) error {
	var present int
	row := ex.QueryRowContext(ctx, `SELECT count(*) FROM sqlite_master WHERE type='table' AND name='client_sessions'`)
	if err := row.Scan(&present); err != nil {
		return err
	}
	if present == 0 {
		return nil
	}
	// CREATE TABLE IF NOT EXISTS cannot extend a database created by an older
	// client. The nullable reference indexes a sealed journal projection; it
	// neither replaces the message journal nor changes session or writer state.
	var transcriptColumn int
	if err := ex.QueryRowContext(ctx, `SELECT count(*) FROM pragma_table_info('client_sessions') WHERE name='transcript_artifact_id'`).Scan(&transcriptColumn); err != nil {
		return err
	}
	if transcriptColumn == 0 {
		if _, err := ex.ExecContext(ctx, `ALTER TABLE client_sessions ADD COLUMN transcript_artifact_id TEXT`); err != nil {
			return err
		}
	}
	if _, err := ex.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS backup_restore_barriers(project TEXT NOT NULL,run TEXT NOT NULL,restored_at TEXT NOT NULL,PRIMARY KEY(project,run))`); err != nil {
		return err
	}
	if restored {
		if _, err := ex.ExecContext(ctx, `INSERT INTO backup_restore_barriers(project,run,restored_at)
		SELECT s.project_id, s.run_id, ? FROM client_sessions s
		JOIN domain_objects r ON r.kind='Run' AND r.project=s.project_id AND r.id=s.run_id
		WHERE s.sealed_at IS NULL AND s.run_id IS NOT NULL
		AND json_extract(r.body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST')
		ON CONFLICT(project,run) DO UPDATE SET restored_at=excluded.restored_at`, Now()); err != nil {
			return err
		}
	}
	if _, err := ex.ExecContext(ctx, `CREATE TRIGGER IF NOT EXISTS client_session_epoch_no_regression BEFORE UPDATE OF writer_epoch ON client_sessions
		WHEN NEW.writer_epoch < OLD.writer_epoch BEGIN SELECT RAISE(ABORT,'SESSION_EPOCH_REGRESSION'); END;`); err != nil {
		return err
	}
	_, err := ex.ExecContext(ctx, `CREATE TRIGGER IF NOT EXISTS client_session_require_fresh BEFORE UPDATE OF writer_epoch ON client_sessions
		WHEN NEW.writer_epoch > OLD.writer_epoch
		AND NEW.run_id IS NOT NULL
		AND EXISTS(SELECT 1 FROM backup_restore_barriers b WHERE b.project=NEW.project_id AND b.run=NEW.run_id)
		AND EXISTS(SELECT 1 FROM domain_objects r WHERE r.kind='Run' AND r.project=NEW.project_id AND r.id=NEW.run_id
			AND json_extract(r.body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST'))
		AND NOT EXISTS(SELECT 1 FROM runtime_observations o
			WHERE o.project=NEW.project_id AND o.run=NEW.run_id
			AND o.observed_at > (SELECT max(b.restored_at) FROM backup_restore_barriers b WHERE b.project=NEW.project_id AND b.run=NEW.run_id)
			AND json_extract(o.body,'$.children_stopped')=1 AND json_extract(o.body,'$.queue_empty')=1)
		BEGIN SELECT RAISE(ABORT,'RESTORE_FRESH_RECONCILIATION_REQUIRED'); END;`)
	return err
}

func EnsureClientSessionFence(ctx context.Context, ex fenceExec) error {
	return installClientSessionFence(ctx, ex, true)
}

// Ordinary startup installs the invariant triggers without marking active runs
// as restored. Only the restore path may advance the reconciliation barrier.

func upgradeQueueTemplate(ctx context.Context, sqls [][]byte, contracts *Contracts) (string, string, error) {
	if len(sqls) != 23 {
		return "", "", fmt.Errorf("UPGRADE_PLAN_UNSUPPORTED")
	}
	stage, e := os.MkdirTemp("", ".researchos-backup-stage-")
	if e != nil {
		return "", "", e
	}
	defer backupDiscard(stage)
	db, e := store.Open(filepath.Join(stage, "schema.sqlite"))
	if e != nil {
		return "", "", e
	}
	defer db.Close()
	for i, raw := range sqls[:21] {
		if _, e = db.ExecContext(ctx, string(raw)); e != nil {
			return "", "", e
		}
		if _, e = db.ExecContext(ctx, "INSERT INTO schema_migrations(version) VALUES(?)", i+1); e != nil {
			return "", "", e
		}
	}
	if _, e = db.ExecContext(ctx, string(sqls[22])); e != nil {
		return "", "", e
	}
	if e = installClientSessionFence(ctx, db, false); e != nil {
		return "", "", e
	}
	before, e := backupSchema(db)
	if e != nil {
		return "", "", e
	}
	if _, e = (&Service{DB: db, Contracts: contracts}).backupFence(ctx); e != nil {
		return "", "", e
	}
	if e = upgradeQueueMigration(ctx, db, sqls[21], sqls[22]); e != nil {
		return "", "", e
	}
	after, e := backupSchema(db)
	return before, after, e
}

func upgradeQueueMigration(ctx context.Context, db *sql.DB, raw, additive []byte) error {
	if Digest(raw) != upgradeQueueSQLHash || Digest(additive) != upgradeQueueSessionHash {
		return fmt.Errorf("UPGRADE_MIGRATION_HASH")
	}
	versions, e := backupMigrations(db)
	if e != nil || !reflect.DeepEqual(versions, upgradeVersions(21)) {
		return fmt.Errorf("UPGRADE_SOURCE_VERSION")
	}
	before, e := upgradeRows(db)
	if e != nil {
		return e
	}
	tx, e := db.BeginTx(ctx, nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	// The exact additive schema must already exist. Reinstalling it must be a
	// no-op, not a repair of corrupt source state or a reconstruction of sessions.
	if _, e = tx.ExecContext(ctx, string(additive)); e != nil {
		return e
	}
	if e = installClientSessionFence(ctx, tx, false); e != nil {
		return e
	}
	if _, e = tx.ExecContext(ctx, string(raw)); e != nil {
		return e
	}
	if _, e = tx.ExecContext(ctx, "INSERT INTO schema_migrations(version) VALUES(22)"); e != nil {
		return e
	}
	after, e := upgradeQueueRows(tx)
	if e != nil {
		return e
	}
	for table, rows := range before {
		if table == "schema_migrations" {
			continue
		}
		if Hash(rows) != Hash(after[table]) {
			return fmt.Errorf("UPGRADE_MIGRATION_MUTATED_HISTORY: %s", table)
		}
	}
	for table := range upgradeQueueTables {
		if rows, ok := after[table]; !ok || len(rows) != 0 {
			return fmt.Errorf("UPGRADE_QUEUE_NOT_EMPTY: %s", table)
		}
	}
	for table := range after {
		if _, ok := before[table]; !ok && !upgradeQueueTables[table] {
			return fmt.Errorf("UPGRADE_UNEXPECTED_TABLE: %s", table)
		}
	}
	var integrity string
	if e = tx.QueryRowContext(ctx, "PRAGMA integrity_check").Scan(&integrity); e != nil || integrity != "ok" {
		return fmt.Errorf("UPGRADE_TARGET_INTEGRITY")
	}
	check, e := tx.QueryContext(ctx, "PRAGMA foreign_key_check")
	if e != nil {
		return e
	}
	bad := check.Next()
	e = check.Err()
	check.Close()
	if bad || e != nil {
		return fmt.Errorf("UPGRADE_TARGET_REFERENCE")
	}
	return tx.Commit()
}

func upgradeQueueLocal(ctx context.Context, opt LocalUpgradeOptions, verifier upgradeVerifier) (RestoreReport, error) {
	report := RestoreReport{Started: Now(), Status: "FAILED"}
	if e := upgradePaths(&opt); e != nil {
		return report, e
	}
	sourceRelease, _, e := upgradeQueueRelease(opt.SourceRoot, 21)
	if e != nil {
		return report, e
	}
	targetRelease, sqls, e := upgradeQueueRelease(opt.TargetRoot, 22)
	if e != nil {
		return report, e
	}
	contracts, e := LoadContracts(filepath.Join(opt.TargetRoot, "spec/v2.0/contracts"))
	if e != nil {
		return report, e
	}
	expectedSourceSchema, expectedTargetSchema, e := upgradeQueueTemplate(ctx, sqls, contracts)
	if e != nil {
		return report, e
	}
	key, e := os.ReadFile(opt.KeyFile)
	if e != nil || len(key) != 32 {
		return report, fmt.Errorf("BACKUP_KEY_UNAVAILABLE")
	}
	defer clear(key)
	db, e := upgradeOpenExclusive(ctx, opt.Source)
	if e != nil {
		return report, e
	}
	defer db.Close() // The native source lock spans snapshot through publication.
	versions, e := backupMigrations(db)
	if e != nil || !reflect.DeepEqual(versions, upgradeVersions(21)) {
		return report, fmt.Errorf("UPGRADE_SOURCE_VERSION: require exact 1..21")
	}
	schema, e := backupSchema(db)
	if e != nil || schema != expectedSourceSchema {
		return report, fmt.Errorf("UPGRADE_SOURCE_SCHEMA")
	}
	guard := &upgradeQueueProtection{upgradeProtection: upgradeProtection{ctx: ctx, verifier: verifier}, contracts: contracts}
	if e = guard.refresh(db); e != nil {
		return report, e
	}
	// Reject any host-side protected storage before reading ordinary BLOB rows
	// for the logical inventory or creating a snapshot.
	original, e := upgradeRows(db)
	if e != nil {
		return report, e
	}
	workspaceIdentity, e := upgradeQueueWorkspaceIdentity(db, opt)
	if e != nil {
		return report, e
	}
	programHashes := Object{}
	for name, path := range map[string]string{"source": opt.SourceProgram, "target": opt.TargetProgram} {
		raw, e := os.ReadFile(path)
		if e != nil {
			return report, e
		}
		programHashes[name] = Digest(raw)
	}
	host, e := os.Hostname()
	if e != nil || host == "" {
		return report, fmt.Errorf("UPGRADE_HOST_UNAVAILABLE")
	}
	plan := Object{"id": opt.Plan, "source_versions": versions, "target_versions": upgradeVersions(22),
		"source_schema_hash": schema, "target_schema_with_restore_fence_hash": expectedTargetSchema,
		"source_release_hash": Hash(sourceRelease), "target_release_hash": Hash(targetRelease),
		"migration_sql_hash": Digest(sqls[21]), "source_database_logical_hash": Hash(original),
		"source_release_manifest": sourceRelease, "target_release_manifest": targetRelease, "operational_row_manifest_hash": guard.operationalHash,
		"workspace_identity_manifest_hash": Hash(workspaceIdentity),
		"program_hashes":                   programHashes, "host_binding_hash": Hash(host), "service_summary_hash": guard.summaryHash,
		"source_path_hash": Hash(opt.Source), "target_path_hash": Hash(opt.Destination)}
	purpose := Object{"kind": "SAME_HOST_CONTROL_PLANE_UPGRADE", "scope": "SameHostExternalReferenceContinuityOnly",
		"plan": plan, "plan_hash": Hash(plan), "protected_reference_versions": guard.count,
		"protected_reference_digest": guard.referencesHash, "protected_payloads_included": false,
		"protected_payloads_revalidated": false, "recovery_dependency": "ORIGINAL_PROTECTED_SERVICE",
		"external_actions_dispatched": 0, "source_ownership": "SQLITE_EXCLUSIVE_UNTIL_TARGET_PUBLICATION",
		"cutover_requirement": "Keep original application and workers stopped until independent review and single-writer cutover; do not run both authorities."}
	policy := &backupPolicy{format: localUpgradeFormat, databaseName: "researchos.sqlite", purpose: purpose, validate: guard.refresh, allowProtected: guard.artifact}
	policy.preserveQueueUpgradeWorkspaces = func(restored *sql.DB) error {
		if e := guard.refresh(restored); e != nil {
			return e
		}
		rows, e := upgradeRows(restored)
		if e != nil || Hash(rows) != Hash(original) {
			return fmt.Errorf("UPGRADE_SNAPSHOT_HISTORY_MISMATCH")
		}
		identity, e := upgradeQueueWorkspaceIdentity(restored, opt)
		if e != nil || Hash(identity) != Hash(workspaceIdentity) {
			return fmt.Errorf("UPGRADE_WORKSPACE_IDENTITY_CHANGED")
		}
		return nil
	}
	policy.beforeRecovery = func(restored *sql.DB) error {
		rows, e := upgradeRows(restored)
		if e != nil || Hash(rows) != Hash(original) {
			return fmt.Errorf("UPGRADE_SNAPSHOT_HISTORY_MISMATCH")
		}
		return nil
	}
	policy.afterRecovery = func(restored *sql.DB) error {
		identity, err := upgradeQueueWorkspaceIdentity(restored, opt)
		if err != nil || Hash(identity) != Hash(workspaceIdentity) {
			return fmt.Errorf("UPGRADE_WORKSPACE_IDENTITY_CHANGED")
		}
		currentSchema, e := backupSchema(restored)
		if e != nil || currentSchema != expectedTargetSchema {
			return fmt.Errorf("UPGRADE_TARGET_SCHEMA")
		}
		rows, e := upgradeRows(restored)
		if e != nil {
			return e
		}
		if e = upgradeQueueRecoveryInvariant(original, rows, opt.Destination); e != nil {
			return e
		}
		sourceNow, e := upgradeRows(db)
		if e != nil || Hash(sourceNow) != Hash(original) {
			return fmt.Errorf("UPGRADE_SOURCE_DRIFT")
		}
		// Release roots and binary files must not change during the operation.
		for _, entry := range []struct {
			root string
			n    int
			hash string
		}{
			{opt.SourceRoot, 21, Hash(sourceRelease)}, {opt.TargetRoot, 22, Hash(targetRelease)},
		} {
			current, _, err := upgradeQueueRelease(entry.root, entry.n)
			if err != nil || Hash(current) != entry.hash {
				return fmt.Errorf("UPGRADE_RELEASE_CHANGED")
			}
		}
		for name, path := range map[string]string{"source": opt.SourceProgram, "target": opt.TargetProgram} {
			raw, err := os.ReadFile(path)
			if err != nil || Digest(raw) != programHashes[name] {
				return fmt.Errorf("UPGRADE_PROGRAM_CHANGED")
			}
		}
		return ctx.Err()
	}
	svc := &Service{DB: db, Contracts: contracts}
	if _, e = svc.createBackupPolicy(ctx, opt.Snapshot, key, policy); e != nil {
		return report, e
	}
	return restoreBackupPolicy(ctx, opt.Snapshot, opt.Destination, RestoreOptions{
		Key: key, SupportedMigrations: versions, Contracts: contracts,
		Migration: func(ctx context.Context, target *sql.DB) error {
			return upgradeQueueMigration(ctx, target, sqls[21], sqls[22])
		},
	}, policy)
}

func upgradeQueueRelease(root string, count int) (Object, [][]byte, error) {
	if count != 21 && count != 22 {
		return nil, nil, fmt.Errorf("UPGRADE_PLAN_UNSUPPORTED")
	}
	files, e := filepath.Glob(filepath.Join(root, "migrations/sqlite/0*.sql")) // release inputs are the numbered migrations only; unnumbered additive files (e.g. next_v24_sessions.sql) are applied through their own single-transaction path
	if e != nil || len(files) != count {
		return nil, nil, fmt.Errorf("UPGRADE_RELEASE_MIGRATIONS: require exact 1..%d", count)
	}
	manifest := Object{}
	sqls := make([][]byte, count+1)
	for i, file := range files {
		name := filepath.Base(file)
		if len(name) < 5 || name[:4] != fmt.Sprintf("%04d", i+1) {
			return nil, nil, fmt.Errorf("UPGRADE_RELEASE_MIGRATIONS")
		}
		raw, e := os.ReadFile(file)
		expected := upgradeMigrationHashes[name]
		if name == "0021_research_pending_windows.sql" {
			expected = "sha256:36d4e5c93aa1edcd7ca5aca922b3bea11d5739f307bd11c6834936adf5552f32"
		}
		if name == "0022_client_command_queue.sql" {
			expected = upgradeQueueSQLHash
		}
		if e != nil || Digest(raw) != expected {
			return nil, nil, fmt.Errorf("UPGRADE_RELEASE_HASH: %s", name)
		}
		manifest["migrations/sqlite/"+name] = Digest(raw)
		sqls[i] = raw
	}
	for name, expected := range map[string]string{
		"domain.schema.json": "sha256:b11439c80d15c9481d7940c98eb6517b5156470f871c839e505a8dce40e0b847",
		"openapi.json":       "sha256:f1edd7955a1d134a675c5558618756db809d82729f8eebe622a9bc2605a58920",
	} {
		raw, e := os.ReadFile(filepath.Join(root, "spec/v2.0/contracts", name))
		if e != nil || Digest(raw) != expected {
			return nil, nil, fmt.Errorf("UPGRADE_CONTRACT_HASH: %s", name)
		}
		manifest["spec/v2.0/contracts/"+name] = expected
	}
	additive, e := os.ReadFile(filepath.Join(root, "migrations/sqlite/next_v24_sessions.sql"))
	if e != nil || Digest(additive) != upgradeQueueSessionHash {
		return nil, nil, fmt.Errorf("UPGRADE_SESSION_SCHEMA_HASH")
	}
	manifest["migrations/sqlite/next_v24_sessions.sql"] = Digest(additive)
	sqls[count] = additive
	return manifest, sqls, nil
}

func (s *Service) backupFence(ctx context.Context) (Object, error) {
	runs, e := backupObjects(s.DB, "SELECT body FROM domain_objects WHERE kind='Run' AND json_extract(body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST')")
	if e != nil {
		return nil, e
	}
	effects, e := backupObjects(s.DB, `SELECT body FROM resource_effects x WHERE sequence=(SELECT max(y.sequence) FROM resource_effects y WHERE y.project=x.project AND y.run=x.run AND y.effect_key=x.effect_key) AND json_extract(body,'$.state') IN ('PREPARED','STARTED','UNKNOWN')`)
	if e != nil {
		return nil, e
	}
	tx, e := s.DB.BeginTx(ctx, nil)
	if e != nil {
		return nil, e
	}
	defer tx.Rollback()
	// Restore-local guard survives restart and applies to every existing resume
	// route. A snapshot's old observation is never fresh reconciliation evidence.
	if _, e = tx.Exec(`CREATE TABLE IF NOT EXISTS backup_restore_barriers(project TEXT NOT NULL,run TEXT NOT NULL,restored_at TEXT NOT NULL,PRIMARY KEY(project,run));
CREATE TRIGGER IF NOT EXISTS backup_require_fresh_observation BEFORE UPDATE ON domain_objects
WHEN NEW.kind='Run' AND json_extract(NEW.body,'$.lease_epoch')>json_extract(OLD.body,'$.lease_epoch')
AND EXISTS(SELECT 1 FROM backup_restore_barriers b WHERE b.project=NEW.project AND b.run=NEW.id)
AND NOT EXISTS(SELECT 1 FROM runtime_observations o JOIN backup_restore_barriers b ON b.project=o.project AND b.run=o.run WHERE o.project=NEW.project AND o.run=NEW.id AND o.epoch=json_extract(OLD.body,'$.lease_epoch') AND o.observed_at>b.restored_at AND json_extract(o.body,'$.children_stopped')=1 AND json_extract(o.body,'$.queue_empty')=1)
BEGIN SELECT RAISE(ABORT,'RESTORE_FRESH_RECONCILIATION_REQUIRED'); END;`); e != nil {
		return nil, e
	}
	if e = EnsureClientSessionFence(ctx, tx); e != nil {
		return nil, e
	}
	if e = fenceRestoredClientQueues(tx); e != nil {
		return nil, e
	}
	if _, e = tx.Exec("UPDATE auth_credentials SET revoked=1"); e != nil {
		return nil, e
	}
	for _, r := range runs {
		if _, e = tx.Exec("INSERT INTO backup_restore_barriers(project,run,restored_at) VALUES(?,?,?) ON CONFLICT(project,run) DO UPDATE SET restored_at=excluded.restored_at", r["project_id"], r["id"], Now()); e != nil {
			return nil, e
		}
		status := "RECONCILING"
		if r["status"] == "CANCEL_REQUESTED" {
			status = "CANCEL_REQUESTED"
		}
		Merge(r, Object{"status": status, "lease_token_hash": Digest([]byte(ID() + ID())), "lease_expires_at": "1970-01-01T00:00:00Z"})
		if e = bump(r); e != nil {
			return nil, e
		}
		if e = s.put(tx, "Run", r); e != nil {
			return nil, e
		}
		if e = s.event(tx, Str(r, "project_id"), "Run", r, "restore-local-admin", ID(), "RUN_CHANGED"); e != nil {
			return nil, e
		}
	}
	for _, o := range effects {
		o["state"] = "UNKNOWN"
		o["restore_reason"] = "SNAPSHOT_MAY_PREDATE_EXTERNAL_DISPATCH"
		if e = effectAppend(tx, Str(o, "project_id"), Str(o, "run_id"), Str(o, "key"), o); e != nil {
			return nil, e
		}
	}
	if e = tx.Commit(); e != nil {
		return nil, e
	}
