}

func backupSchema(db *sql.DB) (string, error) {
	rows, e := db.Query("SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name")
	if e != nil {
		return "", e
	}
	defer rows.Close()
	all := []any{}
	for rows.Next() {
		var kind, name, table, sqlText string
		if e = rows.Scan(&kind, &name, &table, &sqlText); e != nil {
			return "", e
		}
		all = append(all, []any{kind, name, table, sqlText})
	}
	return Hash(all), rows.Err()
}

func New(db *sql.DB, contractsDir, migrationFile string) (*Service, error) {
	c, e := LoadContracts(contractsDir)
	if e != nil {
		return nil, e
	}
	files, e := filepath.Glob(filepath.Join(filepath.Dir(migrationFile), "[0-9][0-9][0-9][0-9]_*.sql"))
	if e != nil {
		return nil, e
	}
	if _, e = os.Stat(migrationFile); e != nil {
		return nil, e
	}
	if e = CheckMigrationSafety(db, files); e != nil {
		return nil, e
	}
	tx, e := db.Begin()
	if e != nil {
		return nil, e
	}
	defer tx.Rollback()
	for _, file := range files {
		version, err := strconv.Atoi(filepath.Base(file)[:4])
		if err != nil {
			return nil, err
		}
		if version < 2 {
			continue
		}
		var applied int
		if err := tx.QueryRow("SELECT count(*) FROM schema_migrations WHERE version=?", version).Scan(&applied); err != nil {
			return nil, err
		}
		if applied != 0 {
			continue
		}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if _, err = tx.Exec(string(b)); err != nil {
			return nil, err
		}
		if _, err = tx.Exec("INSERT OR IGNORE INTO schema_migrations(version) VALUES(?)", version); err != nil {
			return nil, err
		}
	}
	if e = tx.Commit(); e != nil {
		return nil, e
	}
	return &Service{DB: db, Contracts: c}, nil
}

